import{_ as s,o as t,c as i,a4 as a}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"Copie distante chiffrée","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Copie distante chiffrée","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/referent/copie-distante-chiffree.md","filePath":"documentation/referent/copie-distante-chiffree.md"}'),n={name:"documentation/referent/copie-distante-chiffree.md"};function r(o,e,c,d,u,l){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="copie-distante-chiffrée" tabindex="-1">Copie distante chiffrée <a class="header-anchor" href="#copie-distante-chiffrée" aria-label="Permalink to &quot;Copie distante chiffrée {#copie-distante-chiffrée}&quot;">​</a></h1><p>Une sauvegarde au même endroit que l&#39;instance ne protège pas d&#39;une perte du serveur. La <strong>copie distante</strong> envoie chaque sauvegarde chez un hébergeur de votre choix, <strong>chiffrée avant de quitter le serveur</strong> : l&#39;hébergeur ne peut rien lire. Elle repose sur <a href="https://restic.net" target="_blank" rel="noreferrer">restic</a> (<a href="/teuthis-cms-distribution/developpeurs/adr/0070-copie-distante-chiffree-des-sauvegardes-par-restic">ADR-0070</a>) et accepte deux destinations :</p><ul><li><strong>S3 compatible</strong> : Scaleway, OVH, Backblaze B2, Wasabi, MinIO… Il vous faut un compartiment (<em>bucket</em>), un identifiant et un secret d&#39;accès <strong>avec droits de lecture ET d&#39;écriture</strong>.</li><li><strong>SFTP</strong> : un serveur que vous administrez, ou un stockage SSH. Il vous faut un compte et un dossier ; vous y déposerez une clé publique que la commande crée pour vous.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> copie-distante</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> configurer</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">      # questions, essai, puis mot de passe affiché</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> copie-distante</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> etat</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">            # dernière copie réussie, échec éventuel</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> copie-distante</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> essayer</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">         # copie la dernière sauvegarde maintenant</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> copie-distante</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> verifier</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">        # relit l&#39;intégrité du dépôt distant</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sudo</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> copie-distante</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> desactiver</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">      # arrête les copies</span></span></code></pre></div><h2 id="configurer" tabindex="-1">Configurer <a class="header-anchor" href="#configurer" aria-label="Permalink to &quot;Configurer {#configurer}&quot;">​</a></h2><p><code>configurer</code> pose ses questions (destination, point d&#39;accès, compartiment… ; hôte, port, utilisateur, chemin), puis <strong>essaie avant d&#39;enregistrer</strong> : il se connecte, crée le dépôt chiffré (ou rouvre un dépôt existant), <strong>écrit un petit instantané d&#39;essai</strong> et le retire. Si quelque chose échoue (destination injoignable, droits en lecture seule, mauvais mot de passe d&#39;un dépôt existant…), il le dit et <strong>n&#39;enregistre rien</strong> : la configuration précédente reste en place.</p><p>Pour SFTP, il crée une <strong>clé SSH dédiée</strong> (ed25519), affiche la <strong>clé publique</strong> à ajouter aux <code>authorized_keys</code> de votre compte, attend, puis montre les <strong>empreintes de l&#39;hôte</strong> : comparez-les à celles de votre fournisseur avant de confirmer. L&#39;empreinte est enregistrée et <strong>vérifiée à chaque copie</strong> ; un hôte qui change d&#39;empreinte est refusé, jamais contourné.</p><blockquote><p><strong>Le mot de passe du dépôt est affiché UNE seule fois, à la fin.</strong> Notez-le tout de suite et gardez-le <strong>hors du serveur</strong> (gestionnaire de mots de passe, coffre, copie papier). <strong>Sans lui, la copie est illisible — pour tout le monde, hébergeur compris, et pour vous. Il n&#39;existe aucun moyen de le retrouver.</strong> Il est aussi stocké sur le serveur (<code>/opt/teuthis/copie-distante/mot-de-passe</code>, droits 600) pour que les copies partent chaque nuit, mais un serveur perdu emporte ce fichier avec lui.</p></blockquote><p>Sans terminal (script), tout se donne par options et variables : <code>--type s3|sftp</code>, <code>--point-acces</code>, <code>--region</code>, <code>--compartiment</code>, <code>--prefixe</code> ; <code>--hote</code>, <code>--port</code>, <code>--utilisateur</code>, <code>--chemin</code>, <code>--empreinte-hote SHA256:…</code> (obligatoire : jamais acceptée à l&#39;aveugle) ; les identifiants S3 par <code>TEUTHIS_COPIE_S3_IDENTIFIANT</code> et <code>TEUTHIS_COPIE_S3_SECRET</code>. <strong>Un mot de passe ou un secret ne se donne jamais en argument</strong> (il serait lisible par tous dans <code>ps</code>) : la commande refuse. Pour SFTP, <code>sudo teuthis copie-distante cle-ssh</code> crée et affiche la clé publique à l&#39;avance.</p><h2 id="ce-qui-se-passe-ensuite" tabindex="-1">Ce qui se passe ensuite <a class="header-anchor" href="#ce-qui-se-passe-ensuite" aria-label="Permalink to &quot;Ce qui se passe ensuite {#ce-qui-se-passe-ensuite}&quot;">​</a></h2><ul><li><strong>Chaque sauvegarde réussie est copiée dans la minute</strong> (la nocturne comme <code>teuthis sauvegarder</code>). Rien n&#39;est envoyé tant que rien n&#39;est configuré : le service reste inactif et sain.</li><li><strong>Conservation distante</strong> : les 7 derniers jours, 4 semaines et 6 mois ; le reste est purgé.</li><li><strong>Vérification</strong> : une fois par jour, un dixième des données du dépôt est relu (tout le dépôt en dix jours).</li><li><strong>Surveillance</strong> : <code>sudo teuthis etat</code> montre la dernière copie réussie et alerte au-delà de <strong>26 h</strong> ; si une copie échoue, <code>sauvegardes/COPIE-DISTANTE-ECHEC.txt</code> donne le motif et les services <code>copie-distante</code> et <code>sauvegarde</code> passent <strong><code>unhealthy</code></strong>. Un échec de la seule copie distante ne bloque pas <code>teuthis mettre-a-jour</code>. <code>sudo teuthis diagnostic</code> ajoute l&#39;état de la copie, sans aucun secret.</li><li>Le dépôt grossit à peu près comme la somme des sauvegardes conservées : les archives locales sont compressées et se prêtent mal à la déduplication.</li></ul>`,11)])])}const g=s(n,[["render",r]]);export{h as __pageData,g as default};
